/** marker 的 url(#id) 是文件層級解析，同頁其他圖也有 arw/arw-ac/arw-sf，故加前綴。 */
function ArrowMarkers() {
  return (
    <defs>
      <marker id="rfdri-arw" markerWidth="8" markerHeight="6" refX="7" refY="3" orient="auto">
        <polygon points="0 0, 8 3, 0 6" fill={MUTED} />
      </marker>
      <marker id="rfdri-arw-ac" markerWidth="8" markerHeight="6" refX="7" refY="3" orient="auto">
        <polygon points="0 0, 8 3, 0 6" fill={ACCENT} />
      </marker>
      <marker id="rfdri-arw-sf" markerWidth="8" markerHeight="6" refX="7" refY="3" orient="auto">
        <polygon points="0 0, 8 3, 0 6" fill={SOFT} />
      </marker>
    </defs>
  );
}

function FlowEdge({ edge, active }: { edge: EdgeDef; active: boolean }) {
  const stroke = active ? ACCENT : edge.soft ? SOFT : MUTED;
  const marker = active ? 'rfdri-arw-ac' : edge.soft ? 'rfdri-arw-sf' : 'rfdri-arw';
  return (
    <g>
      <path
        d={edge.d}
        fill="none"
        stroke={stroke}
        strokeWidth={active ? 2.2 : 1.2}
        strokeDasharray={edge.dash}
        strokeOpacity={active ? 1 : 0.85}
        markerEnd={`url(#${marker})`}
      />
      {edge.box && (
        <rect x={edge.box.x} y={edge.box.y} width={edge.box.w} height={edge.box.h} rx="2" fill={PAPER} />
      )}
      {edge.labels.map((label) => (
        <text
          key={label.text}
          x={label.x}
          y={label.y}
          fontSize={label.size ?? 8}
          fontFamily={MONO}
          textAnchor={label.anchor}
          fill={active ? ACCENT : edge.soft ? SOFT : MUTED}
        >
          {label.text}
        </text>
      ))}
    </g>
  );
}

function FlowNode({
  node,
  active,
  current,
  onActivate,
}: {
  node: NodeDef;
  active: boolean;
  current: boolean;
  /** null 代表此節點目前不可點（尚未解鎖或本來就是說明性節點）。 */
  onActivate: (() => void) | null;
}) {
  const keyActivate = (event: KeyboardEvent<SVGGElement>) => {
    if (onActivate && (event.key === 'Enter' || event.key === ' ')) {
      event.preventDefault();
      onActivate();
    }
  };

  const body = (
    <>
      {current && (
        <rect
          x={node.x - 6}
          y={node.y - 6}
          width={node.w + 12}
          height={node.h + 12}
          rx={node.rx + 4}
          fill="none"
          stroke={ACCENT}
          strokeWidth="2.4"
        />
      )}
      {node.points ? (
        <polygon
          points={node.points}
          fill={node.fill}
          stroke={active ? ACCENT : node.stroke}
          strokeWidth={active ? 1.6 : 1}
          strokeOpacity={active ? 1 : 0.6}
        />
      ) : (
        <>
          <rect x={node.x} y={node.y} width={node.w} height={node.h} rx={node.rx} fill={PAPER} />
          <rect
            x={node.x}
            y={node.y}
            width={node.w}
            height={node.h}
            rx={node.rx}
            fill={node.fill}
            stroke={active ? ACCENT : node.stroke}
            strokeWidth={active ? 1.6 : 1}
            strokeDasharray={node.dash}
            strokeOpacity={active ? 1 : 0.6}
          />
        </>
      )}
      <text
        x={node.cx}
        y={node.titleY}
        fontSize="12"
        fontWeight="600"
        textAnchor="middle"
        fill={INK}
      >
        {node.title}
      </text>
      {node.subs.map((sub) => (
        <text
          key={sub.text}
          x={node.cx}
          y={sub.y}
          fontSize="9"
          fontFamily={MONO}
          textAnchor="middle"
          fill={sub.soft ? SOFT : MUTED}
        >
          {sub.text}
        </text>
      ))}
    </>
  );

  // 不可點的節點仍要帶 aria-current，否則整批流程那個「目前在這」的節點
  // 只有視覺高亮、輔助科技讀不到。
  if (!onActivate) return <g aria-current={current ? 'step' : undefined}>{body}</g>;

  return (
    <g
      role="button"
      tabIndex={0}
      aria-label={`節點：${node.title}`}
      aria-current={current ? 'step' : undefined}
      style={{ cursor: 'pointer' }}
      onClick={onActivate}
      onKeyDown={keyActivate}
    >
      {body}
    </g>
  );
}

/** 依決策／仲裁／例外處置，算出目前該點亮哪幾條線。 */
function computeActiveEdges(state: SingleFlowState): string[] {
  const edges = ['submit-review', 'review-decide'];
  if (state.decision === null) return edges;
  if (state.decision === 'approve') {
    edges.push('decide-finalized');
    return edges;
  }
  edges.push('decide-dispute', 'dispute-arbitrate');
  if (state.arbitration === null) return edges;
  if (state.arbitration !== 'reject') {
    edges.push('arbitrate-finalized');
    return edges;
  }
  edges.push('arbitrate-exception', 'exception-owner');
  if (state.exceptionAction === 'exclude_from_dataset') edges.push('owner-removed');
  else if (state.exceptionAction !== null) edges.push('owner-finalized');
  return edges;
}

function SingleFlowDiagram({
  state,
  path,
  onJump,
}: {
  state: SingleFlowState;
  path: number[];
  onJump: (step: number) => void;
}) {
  const activeEdges = computeActiveEdges(state);
  const currentIndex = path.indexOf(state.step);

  // NoteCraft 的 Tailwind 產出不含 overflow-x-auto（實測 computed 為 visible），
  // 外層 figure 又是 overflow-x:hidden，靠 class 會被硬裁掉且無法捲動；
  // 故與 MDX 內嵌原圖一致，改用 inline style。
  return (
    <div style={{ overflowX: 'auto' }}>
      <svg
        viewBox="24 12 920 704"
        role="group"
        aria-label="試標單筆審核流程圖，可點擊節點跳到該步驟"
        style={{ width: '100%', minWidth: 800, display: 'block', fontFamily: 'Inter, "Noto Sans TC", sans-serif' }}
      >
        <rect x="24" y="12" width="920" height="704" fill={PAPER} />
        <ArrowMarkers />

        <text x="40" y="32" fill={MUTED} fontSize="8" fontFamily={MONO} letterSpacing="0.18em">
          單筆流程 · 一份樣本搭一位標記員
        </text>

        {SINGLE_EDGES.map((edge) => (
          <FlowEdge key={edge.id} edge={edge} active={activeEdges.includes(edge.id)} />
        ))}

        {/* 審核員逐份審核底下的附註藥丸：不是節點，不可點 */}
        <rect x="340" y="200" width="120" height="24" rx="12" fill="rgba(30,27,75,0.05)" stroke={MUTED} strokeWidth="1" />
        <text x="400" y="216" fill={MUTED} fontSize="9" fontFamily={MONO} textAnchor="middle">
          按下送出審核才算數
        </text>

        {SINGLE_NODES.map((node) => {
          const stepIndex = node.step === null ? -1 : path.indexOf(node.step);
          const unlocked = stepIndex !== -1;
          // 只有已經走過的節點可點；stepIndex === -1（不在目前路徑上）也算沒走過，
          // 否則 -1 <= currentIndex 會讓還沒解鎖的節點誤判成可點。
          const reached = stepIndex !== -1 && currentIndex !== -1 && stepIndex <= currentIndex;
          return (
            <FlowNode
              key={node.id}
              node={node}
              active={unlocked}
              current={node.step === state.step}
              onActivate={reached ? () => onJump(node.step as number) : null}
            />
          );
        })}
      </svg>
    </div>
  );
}

function BatchFlowDiagram({
  judgment,
  onJudge,
}: {
  judgment: BatchJudgment | null;
  onJudge: (next: BatchJudgment) => void;
}) {
  const activeEdges = [
    'submitted-pending',
    'raw-consistency',
    'settled-rate',
    'consistency-judge',
    'rate-judge',
    'settled-feedback',
    'feedback-annotator',
  ];
  if (judgment === 'acceptable') activeEdges.push('judge-open');
  if (judgment === 'unacceptable') activeEdges.push('judge-revise');

  const OUTCOME_OF: Record<string, BatchJudgment> = {
    'open-official': 'acceptable',
    'revise-guideline': 'unacceptable',
  };

  return (
    <div style={{ overflowX: 'auto' }}>
      <svg
        viewBox="24 740 1152 424"
        role="group"
        aria-label="試標整批判讀流程圖，可點擊兩個出口節點決定判讀結果"
        style={{ width: '100%', minWidth: 1000, display: 'block', fontFamily: 'Inter, "Noto Sans TC", sans-serif' }}
      >
        <rect x="24" y="740" width="1152" height="424" fill={PAPER} />
        <ArrowMarkers />

        <line x1="40" y1="748" x2="1160" y2="748" stroke="rgba(30,27,75,0.10)" strokeWidth="0.8" />
        <text x="40" y="764" fill={MUTED} fontSize="8" fontFamily={MONO} letterSpacing="0.18em">
          整批流程 · 全部試標跑完之後
        </text>

        {BATCH_EDGES.map((edge) => (
          <FlowEdge key={edge.id} edge={edge} active={activeEdges.includes(edge.id)} />
        ))}

        {BATCH_NODES.map((node) => {
          const outcome = OUTCOME_OF[node.id];
          return (
            <FlowNode
              key={node.id}
              node={node}
              active={outcome === undefined || judgment === outcome}
              current={
                outcome === undefined ? node.id === 'owner-judges' && judgment === null : judgment === outcome
              }
              onActivate={outcome === undefined ? null : () => onJudge(outcome)}
            />
          );
        })}

        <text
          x="40"
          y="1144"
          fill={MUTED}
          fontSize="14"
          fontStyle="italic"
          fontFamily='"Crimson Pro", "Noto Serif TC", Georgia, serif'
        >
          審核員的每一次決定只影響一份標記；要整批跑完，才看得出指引哪裡不夠清楚。
        </text>
      </svg>
    </div>
  );
}

