function SingleUnitFlow() {
  const [state, setState] = useState<SingleFlowState>(INITIAL_SINGLE_STATE);
  const path = computeVisiblePath(state.decision, state.arbitration, state.exceptionConfirmed);
  const currentDef = STEP_DEFS[state.step];
  const canGoPrev = path.indexOf(state.step) > 0;
  const canGoNext = computeCanGoNext(state, path);

  function moveTo(s: SingleFlowState, step: number): SingleFlowState {
    return { ...s, step, finalized: s.finalized || step === 7 };
  }

  function jumpTo(id: number) {
    setState((s) => moveTo(s, id));
  }

  function goPrev() {
    const idx = path.indexOf(state.step);
    if (idx > 0) setState((s) => moveTo(s, path[idx - 1]));
  }

  function goNext() {
    const idx = path.indexOf(state.step);
    if (idx !== -1 && idx < path.length - 1) setState((s) => moveTo(s, path[idx + 1]));
  }

  function selectDecision(next: ReviewDecision) {
    setState((s) => s.finalized ? s : ({
      ...s,
      decision: next,
      arbitration: null,
      exceptionAction: null,
      exceptionReason: '',
      exceptionConfirmed: false,
    }));
  }

  function selectArbitration(next: ArbitrationOutcome) {
    setState((s) => s.finalized ? s : ({
      ...s,
      arbitration: next,
      exceptionAction: null,
      exceptionReason: '',
      exceptionConfirmed: false,
    }));
  }

  function selectExceptionAction(next: ExceptionAction) {
    setState((s) => (s.finalized ? s : { ...s, exceptionAction: next }));
  }

  function setExceptionReason(value: string) {
    setState((s) => (s.finalized ? s : { ...s, exceptionReason: value }));
  }

  function confirmException() {
    setState((s) => {
      if (!s.exceptionAction || s.exceptionReason.trim().length === 0) return s;
      return moveTo({ ...s, exceptionConfirmed: true }, 7);
    });
  }

  function reset() {
    setState(INITIAL_SINGLE_STATE);
  }

  return (
    <div className="space-y-4">
      <SingleFlowDiagram state={state} path={path} onJump={jumpTo} />
      <StepDetailPanel id={state.step} label={currentDef.label} detail={currentDef.detail} />
      {state.finalized && [3, 5, 6].includes(state.step) && <LockedNotice onReset={reset} />}
      {state.step === 3 && <DecisionButtons decision={state.decision} locked={state.finalized} onSelect={selectDecision} />}
      {state.step === 5 && (
        <ArbitrationButtons arbitration={state.arbitration} locked={state.finalized} onSelect={selectArbitration} />
      )}
      {state.step === 6 && (
        <ExceptionPoolPanel
          state={state}
          locked={state.finalized}
          onSelectAction={selectExceptionAction}
          onReasonChange={setExceptionReason}
          onConfirm={confirmException}
        />
      )}
      {state.step === 7 && <FinalizedTrace state={state} onReset={reset} />}
      <StepNav canGoPrev={canGoPrev} canGoNext={canGoNext} onPrev={goPrev} onNext={goNext} />
    </div>
  );
}

// ---------------------------------------------------------------------------
// Batch summary
// ---------------------------------------------------------------------------

interface ModifiedRateDatum {
  readonly name: string;
  readonly rate: number;
}

const MODIFIED_RATE_DATA: ModifiedRateDatum[] = [
  { name: '標記員 A', rate: 18 },
  { name: '標記員 B', rate: 32 },
  { name: '標記員 C', rate: 24 },
];

const CONSISTENCY_RATE = 82;

function ConsistencyStat() {
  return (
    <div className="rounded-lg border border-slate-200 bg-white p-4">
      <p className="text-4xl font-bold text-indigo-600">{CONSISTENCY_RATE}%</p>
      <p className="mt-1 text-xs text-slate-500">標記一致性（示意數值）</p>
    </div>
  );
}

function ModifiedRateChart() {
  return (
    <div className="rounded-lg border border-slate-200 bg-white p-4">
      <p className="mb-2 text-xs text-slate-500">標記員被修改的比例（示意數值）</p>
      <div style={{ width: '100%', height: 180 }}>
        <ResponsiveContainer>
          <BarChart data={MODIFIED_RATE_DATA} margin={{ top: 4, right: 8, left: 0, bottom: 0 }}>
            <CartesianGrid vertical={false} stroke="#E2E8F0" />
            <XAxis dataKey="name" tick={{ fontSize: 11, fill: '#64748B' }} axisLine={{ stroke: '#E2E8F0' }} tickLine={false} />
            <YAxis tick={{ fontSize: 11, fill: '#64748B' }} axisLine={{ stroke: '#E2E8F0' }} tickLine={false} unit="%" width={36} />
            <Tooltip cursor={{ fill: '#EEF2FF' }} formatter={(value: number) => [`${value}%`, '修正率']} />
            <Bar dataKey="rate" fill="#6366F1" radius={[4, 4, 0, 0]} />
          </BarChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
}

function JudgmentPanel({ judgment }: { judgment: BatchJudgment | null }) {
  let content: ReactNode;
  if (judgment === null) {
    content = (
      <p className="text-xs text-slate-400">
        點流程圖右側的「開放正式標記」或「修改指引後再跑一輪試標」，選擇主持人的判讀結果。
      </p>
    );
  } else if (judgment === 'acceptable') {
    content = (
      <p className="flex items-center gap-1.5 text-sm font-medium text-emerald-700">
        開放正式標記
        <ArrowRight size={16} />
      </p>
    );
  } else {
    content = (
      <div className="space-y-1">
        <p className="text-sm text-slate-700">修改指引 → 再跑一輪試標</p>
        <p className="text-xs text-slate-500">（改的是指引，不是退回個別樣本）</p>
      </div>
    );
  }
  return <div className="rounded-lg border border-slate-200 bg-white p-4">{content}</div>;
}

function FeedbackAside() {
  return (
    <div className="flex gap-2.5 rounded-lg border border-slate-200 bg-white p-3">
      <Eye size={16} className="mt-0.5 shrink-0 text-slate-400" />
      <div>
        <p className="text-xs font-semibold text-slate-600">試標歷程回饋</p>
        <p className="mt-1 text-xs text-slate-500">
          標記員自己看得到哪幾項被改、被誰定案，不用退回也能學到。
        </p>
      </div>
    </div>
  );
}

function BatchSummary() {
  const [judgment, setJudgment] = useState<BatchJudgment | null>(null);
  return (
    <div className="space-y-4">
      <BatchFlowDiagram judgment={judgment} onJudge={setJudgment} />
      <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
        <ConsistencyStat />
        <ModifiedRateChart />
      </div>
      <JudgmentPanel judgment={judgment} />
      <FeedbackAside />
    </div>
  );
}

// ---------------------------------------------------------------------------
// Root component
// ---------------------------------------------------------------------------

export default function ReviewFlowDryRunInteractive() {
  const [mode, setMode] = useState<ScaleMode>('single');
  return (
    <div className="rfdr-root not-prose w-full space-y-5">
      <style dangerouslySetInnerHTML={{ __html: SCOPED_CSS }} />
      <ScaleToggle mode={mode} onChange={setMode} />
      {mode === 'single' ? <SingleUnitFlow /> : <BatchSummary />}
    </div>
  );
}
